import{r as t,C as n,v as p,c as s,w as o,i as e,o as r,a as i,b as l,t as a,D as c,n as g,f as d}from"./index-BPaxSB6c.js";import{_ as h}from"./_plugin-vue_export-helper.BCo6x5W8.js";const u=h({__name:"help-detail",setup(h){const u=t({id:"",icon:"",title:"",content:""}),_={1:{id:1,icon:"📋",title:"如何申请领养",content:"\n\t\t\t<h2>如何申请领养</h2>\n\t\t\t<p>1. 浏览宠物列表，选择您喜欢的宠物</p>\n\t\t\t<p>2. 点击「申请领养」按钮</p>\n\t\t\t<p>3. 填写个人信息和领养申请表单</p>\n\t\t\t<p>4. 提交申请，等待审核</p>\n\t\t\t<p>5. 审核通过后，工作人员会联系您</p>\n\t\t\t<p><strong>注意事项：</strong></p>\n\t\t\t<p>• 请确保填写的联系方式准确</p>\n\t\t\t<p>• 领养需要年满18周岁</p>\n\t\t\t<p>• 请确认您有足够的时间和精力照顾宠物</p>\n\t\t"},2:{id:2,icon:"📝",title:"领养审核需要多久",content:"\n\t\t\t<h2>领养审核需要多久</h2>\n\t\t\t<p>一般情况下，领养审核时间为1-3个工作日。</p>\n\t\t\t<p><strong>审核流程包括：</strong></p>\n\t\t\t<p>1. 工作人员初步审核申请信息</p>\n\t\t\t<p>2. 电话或短信联系申请人核实信息</p>\n\t\t\t<p>3. 确认领养条件和居住环境</p>\n\t\t\t<p>4. 审核通过后通知领养人</p>\n\t\t\t<p><strong>温馨提示：</strong></p>\n\t\t\t<p>• 请保持电话畅通，以便工作人员联系</p>\n\t\t\t<p>• 如需加快审核，可联系在线客服</p>\n\t\t"},3:{id:3,icon:"🐾",title:"领养需要什么条件",content:"\n\t\t\t<h2>领养需要什么条件</h2>\n\t\t\t<p><strong>基本条件：</strong></p>\n\t\t\t<p>• 年满18周岁，具有完全民事行为能力</p>\n\t\t\t<p>• 有固定的住所和稳定的收入</p>\n\t\t\t<p>• 家庭成员同意领养</p>\n\t\t\t<p>• 有足够的时间照顾宠物</p>\n\t\t\t<p><strong>优先条件：</strong></p>\n\t\t\t<p>• 有养宠经验者优先</p>\n\t\t\t<p>• 自有住房者优先</p>\n\t\t\t<p>• 有宠物陪伴经历者优先</p>\n\t\t"},4:{id:4,icon:"💰",title:"支持哪些支付方式",content:"\n\t\t\t<h2>支持哪些支付方式</h2>\n\t\t\t<p>目前支持以下支付方式：</p>\n\t\t\t<p><strong>1. 微信支付</strong> - 推荐使用，安全便捷</p>\n\t\t\t<p><strong>2. 支付宝支付</strong> - 支持支付宝账户支付</p>\n\t\t\t<p><strong>3. 余额支付</strong> - 使用账户余额支付</p>\n\t\t\t<p><strong>温馨提示：</strong></p>\n\t\t\t<p>• 支付过程中请确保网络畅通</p>\n\t\t\t<p>• 如遇支付问题，请联系客服</p>\n\t\t"},5:{id:5,icon:"💳",title:"支付失败怎么办",content:"\n\t\t\t<h2>支付失败怎么办</h2>\n\t\t\t<p><strong>常见原因：</strong></p>\n\t\t\t<p>1. 网络不稳定 - 请切换网络后重试</p>\n\t\t\t<p>2. 账户余额不足 - 请充值后重试</p>\n\t\t\t<p>3. 支付限额 - 可联系银行调整限额</p>\n\t\t\t<p>4. 系统繁忙 - 请稍后再试</p>\n\t\t\t<p><strong>解决方法：</strong></p>\n\t\t\t<p>• 重新发起支付</p>\n\t\t\t<p>• 更换支付方式</p>\n\t\t\t<p>• 联系在线客服处理</p>\n\t\t"},6:{id:6,icon:"🚚",title:"发货时间要多久",content:"\n\t\t\t<h2>发货时间要多久</h2>\n\t\t\t<p>订单支付成功后，我们会在1-3个工作日内发货。</p>\n\t\t\t<p><strong>物流时效：</strong></p>\n\t\t\t<p>• 同城：1-2天送达</p>\n\t\t\t<p>• 省内：2-3天送达</p>\n\t\t\t<p>• 省外：3-5天送达</p>\n\t\t\t<p><strong>温馨提示：</strong></p>\n\t\t\t<p>• 节假日物流可能会有延迟</p>\n\t\t\t<p>• 可联系客服查询物流进度</p>\n\t\t"},7:{id:7,icon:"📍",title:"如何查询物流信息",content:"\n\t\t\t<h2>如何查询物流信息</h2>\n\t\t\t<p><strong>查询方法：</strong></p>\n\t\t\t<p>1. 进入「我的」-「我的订单」</p>\n\t\t\t<p>2. 点击需要查询的订单</p>\n\t\t\t<p>3. 点击「查看物流」按钮</p>\n\t\t\t<p>4. 查看实时物流状态</p>\n\t\t\t<p><strong>温馨提示：</strong></p>\n\t\t\t<p>• 物流信息更新可能有延迟</p>\n\t\t\t<p>• 如长时间未更新，请联系客服</p>\n\t\t"},8:{id:8,icon:"🔄",title:"退换货政策说明",content:"\n\t\t\t<h2>退换货政策说明</h2>\n\t\t\t<p><strong>退换货条件：</strong></p>\n\t\t\t<p>• 商品未拆封、不影响二次销售</p>\n\t\t\t<p>• 收到商品后7天内提出申请</p>\n\t\t\t<p>• 质量问题可在15天内申请</p>\n\t\t\t<p><strong>退换货流程：</strong></p>\n\t\t\t<p>1. 进入「我的」-「我的订单」</p>\n\t\t\t<p>2. 选择需要退换的订单</p>\n\t\t\t<p>3. 点击「申请退款」</p>\n\t\t\t<p>4. 填写退款原因和说明</p>\n\t\t\t<p>5. 提交申请，等待审核</p>\n\t\t"},9:{id:9,icon:"❓",title:"如何申请退款",content:"\n\t\t\t<h2>如何申请退款</h2>\n\t\t\t<p><strong>申请步骤：</strong></p>\n\t\t\t<p>1. 进入「我的」-「我的订单」</p>\n\t\t\t<p>2. 选择需要退款的订单</p>\n\t\t\t<p>3. 点击「申请退款」按钮</p>\n\t\t\t<p>4. 选择退款原因，填写说明</p>\n\t\t\t<p>5. 提交申请，等待商家审核</p>\n\t\t\t<p><strong>退款到账时间：</strong></p>\n\t\t\t<p>• 微信/支付宝支付：1-3个工作日</p>\n\t\t\t<p>• 余额支付：即时到账</p>\n\t\t"},10:{id:10,icon:"🐱",title:"猫咪日常护理指南",content:"\n\t\t\t<h2>猫咪日常护理指南</h2>\n\t\t\t<p><strong>饮食管理：</strong></p>\n\t\t\t<p>• 提供优质的猫粮和充足的清水</p>\n\t\t\t<p>• 定时定量喂食，避免过度肥胖</p>\n\t\t\t<p>• 定期更换猫粮品牌</p>\n\t\t\t<p><strong>健康管理：</strong></p>\n\t\t\t<p>• 定期接种疫苗</p>\n\t\t\t<p>• 定期体内外驱虫</p>\n\t\t\t<p>• 每年进行一次体检</p>\n\t\t\t<p><strong>日常护理：</strong></p>\n\t\t\t<p>• 每日梳毛，保持毛发健康</p>\n\t\t\t<p>• 定期清洁耳朵和眼睛</p>\n\t\t\t<p>• 保持猫砂盆清洁</p>\n\t\t"},11:{id:11,icon:"🐶",title:"狗狗训练入门教程",content:"\n\t\t\t<h2>狗狗训练入门教程</h2>\n\t\t\t<p><strong>基础指令训练：</strong></p>\n\t\t\t<p>1. 坐下：用零食引导狗狗坐下</p>\n\t\t\t<p>2. 握手：轻抬狗狗前爪并给予奖励</p>\n\t\t\t<p>3. 趴下：从坐下姿势引导趴下</p>\n\t\t\t<p>4. 过来：用愉快的语气呼唤狗狗</p>\n\t\t\t<p><strong>训练技巧：</strong></p>\n\t\t\t<p>• 每次训练不超过15分钟</p>\n\t\t\t<p>• 使用零食作为奖励</p>\n\t\t\t<p>• 保持耐心和一致性</p>\n\t\t\t<p>• 正向强化，不惩罚</p>\n\t\t"},12:{id:12,icon:"💉",title:"宠物疫苗接种指南",content:"\n\t\t\t<h2>宠物疫苗接种指南</h2>\n\t\t\t<p><strong>猫咪疫苗接种：</strong></p>\n\t\t\t<p>• 基础免疫：8周、12周、16周各接种一次</p>\n\t\t\t<p>• 加强免疫：每年接种一次</p>\n\t\t\t<p>• 狂犬疫苗：每年接种一次</p>\n\t\t\t<p><strong>狗狗疫苗接种：</strong></p>\n\t\t\t<p>• 基础免疫：6周、9周、12周各接种一次</p>\n\t\t\t<p>• 加强免疫：每年接种一次</p>\n\t\t\t<p>• 狂犬疫苗：每年接种一次</p>\n\t\t\t<p><strong>注意事项：</strong></p>\n\t\t\t<p>• 接种前确保宠物健康</p>\n\t\t\t<p>• 接种后观察30分钟</p>\n\t\t\t<p>• 一周内避免洗澡和剧烈运动</p>\n\t\t"},13:{id:13,icon:"🦷",title:"宠物牙齿护理方法",content:"\n\t\t\t<h2>宠物牙齿护理方法</h2>\n\t\t\t<p><strong>日常护理：</strong></p>\n\t\t\t<p>• 每周给宠物刷牙2-3次</p>\n\t\t\t<p>• 使用宠物专用牙膏和牙刷</p>\n\t\t\t<p>• 提供洁齿骨或洁齿玩具</p>\n\t\t\t<p><strong>专业护理：</strong></p>\n\t\t\t<p>• 每年进行一次专业洁牙</p>\n\t\t\t<p>• 定期检查牙齿和牙龈健康</p>\n\t\t\t<p>• 发现牙结石及时处理</p>\n\t\t\t<p><strong>警示信号：</strong></p>\n\t\t\t<p>• 口臭、流口水增多</p>\n\t\t\t<p>• 进食困难、食欲下降</p>\n\t\t\t<p>• 牙龈红肿、出血</p>\n\t\t"}};n((t=>{const n=Number(t.id);n&&_[n]?u.value=_[n]:p({title:"内容不存在",icon:"none"})}));const f=()=>c(),v=()=>{g({url:"/pages/message/customer-service/customer-service"})};return(t,n)=>{const p=d,c=e;return r(),s(c,{class:"help-detail-page"},{default:o((()=>[i(c,{class:"nav-bar"},{default:o((()=>[i(c,{class:"nav-left",onClick:f},{default:o((()=>[i(p,{class:"back-icon"},{default:o((()=>[l("‹")])),_:1})])),_:1}),i(p,{class:"nav-title"},{default:o((()=>[l(a(u.value.title||"帮助详情"),1)])),_:1}),i(c,{class:"nav-right"})])),_:1}),u.value?(r(),s(c,{key:0,class:"content-wrap"},{default:o((()=>[i(c,{class:"title-section"},{default:o((()=>[i(p,{class:"help-icon"},{default:o((()=>[l(a(u.value.icon),1)])),_:1}),i(p,{class:"help-title"},{default:o((()=>[l(a(u.value.title),1)])),_:1})])),_:1}),i(c,{class:"content-section",innerHTML:u.value.content},null,8,["innerHTML"]),i(c,{class:"tip-section"},{default:o((()=>[i(p,{class:"tip-text"},{default:o((()=>[l("💡 如果以上内容未能解决您的问题")])),_:1}),i(c,{class:"tip-btn",onClick:v},{default:o((()=>[l("联系在线客服")])),_:1})])),_:1})])),_:1})):(r(),s(c,{key:1,class:"loading-container"},{default:o((()=>[i(p,{class:"loading-text"},{default:o((()=>[l("加载中...")])),_:1})])),_:1}))])),_:1})}}},[["__scopeId","data-v-7204fa67"]]);export{u as default};
